theme.css:
.igc-pie-center-text .igc-pie-center-text-node {
	font-family: PT Sans Narrow;
	font-weight: 700;
	fill: #313131;
	font-size: 19px;
}
.igc-sheet {
	margin-bottom: 15px;
}
.igc-sheets {
	margin-bottom: 15px;
}
.igc-sheets .igc-sheet .igc-sheet-label,
    .igc-sheets .igc-sheet:hover .igc-sheet-label,
        .igc-sheets .igc-sheet.active .igc-sheet-label {
	color: rgba(70, 70, 70, 1);
	margin-left: 5px;
	font: 400 13px PT Sans !important;
}
.igc-sheets .igc-sheet:hover .igc-sheet-label,.igc-sheets .igc-sheet.active .igc-sheet-label {
	color: rgba(70, 70, 70, 0.7);
}
.igc-sheets .igc-sheet .igc-sheet-ico,
    .igc-sheets .igc-sheet:hover .igc-sheet-ico {
	background: rgba(167, 167, 167, 0.3);
	border-color: #313131;
	transition: .2s;
}
.igc-sheets .igc-sheet:hover .igc-sheet-ico {
	background: rgba(167, 167, 167, 1);
}
.igc-sheets .igc-sheet.active .igc-sheet-ico {
	background: #313131;
}
.igc-sheets .igc-sheet.active .igc-sheet-ico::after,
    .igc-sheets .igc-sheet:hover .igc-sheet-ico::after {
	height: 6px;
	width: 6px;
	left: 6px;
	top: 6px;
	background: #edede2;
}
.igc-textual-figure {
	font: 400 40px Oswald;
	line-height: 48px;
}
.igc-textual-fact {
	color: #313131;
	line-height: 18px;
	font: 400 15px PT Sans;
}
.igc-textual-icon {
	padding-right: 30px;
	padding-top: 7px;
}
.igc-table .igc-table-cell {
	font: 400 13px PT Sans;
}
.igc-table .igc-table-header {
	font: 400 13px PT Sans;
	padding-left: 9px;
}
.ig-container {
	background: #edede2;
}
.headline {
	font: 400 47px Oswald;
	color: #313131;
	text-align: left;
	line-height: 47px;
}
.chart-title {
	font: 400 40px Oswald;
	color: #313131;
	text-align: left;
	line-height: 40px;
}
.bodytext {
	font: 400 normal 15px PT Sans;
	text-align: left;
	text-align: justify;
	color: #313131;
	line-height: 25px;
}
.quoted {
	padding-bottom: 20px;
}
.quoted:after {
	content: '';
	position: absolute;
	bottom: 0;
	left: 50%;
	margin-left: -20px;
	width: 0;
	height: 0;
	border-style: solid;
	border-width: 20px 20px 0 20px;
	border-color: #313131 transparent transparent transparent;
}
.quote {
	font: 400 40px Oswald;
	color: #fff;
	padding: 30px !important;
	background: #313131;
	line-height: 40px;
	text-align: left;
	text-align: center;
	min-height: 40px;
}
.quotetitle {
	font: 400 15px PT Sans;
	color: #fff;
	margin-top: 5px;
	line-height: 25px;
}
.tt_tooltip {
	color: #fff;
	font: 400 normal 13px PT Sans;
}
.igc-legend-entry {
	margin-top: 15px;
}
.igc-legend {
	padding-top: 10px;
	padding-bottom: 0;
}
.igc-x-axis-separator {
	y2: 30 !important;
}
.footer-bottom {
	padding-top: 15px;
	overflow: hidden;
	margin-bottom: 15px;
}
.ig-share-button {
	margin-bottom: 11px;
}
.ig-logo {
	margin-top: 0px;
}
.headline .innertext:before, .chart-title .innertext:before {
	text-transform: uppercase;
}
.ig-separator-line {
	background: rgba(49, 49, 49, 0.5);
}
.heatmap-legend {
	background: rgba(237, 237, 226, 0.7);
}
.heatmap-legend-item,
.heatmap-label {
	color: #313131;
	font-size: 13px;
	font-weight: 400;
	font-family: PT Sans;
}
.igc-graph-pie-piece {
	stroke: rgb(237, 237, 226);
}
.tt_tooltip .tt_value {
	font-weight: 400;
}
.tt_tooltip .tt_body {
	background: #1d1d1d;
}
.tt_tooltip .tt_left {
	border-right: 8px solid #1d1d1d;
}
.tt_tooltip .tt_right {
	border-left: 8px solid #1d1d1d;
}
.igc-tabs .igc-tab-active {
	background: #edede2;
}
.igc-tabs .igc-tab .igc-tab-content,
          .igc-tabs .igc-tab.icon-down:after {
	font-family: PT Sans;
	color: #313131;
	font-weight: 400;
}
.igc-tabs .igc-tab,
          .igc-tab-switcher {
	color: #313131;
}
.igc-tabs.igc-tabs-dropdown .igc-tab-name {
	font-family: PT Sans;
	color: #313131;
}
.captiontext {
	font-family: PT Sans;
	color: #313131;
	font-weight: 400;
}
.captiontext .innertext {
	line-height: 1.5;
}
.igc-table-search {
	color: #313131;
	font-size: 13px;
	font-weight: 400;
	font-family: PT Sans;
}
